#include "hil/P95P99AcceptanceGate.h"
namespace dnxr { P95P99AcceptanceDecision P95P99AcceptanceGate::evaluate(const HILBenchLatencyEvidence& e,const HILBenchTargets& t) const { P95P99AcceptanceDecision d; if(!e.present){ d.failures.push_back("missing p95/p99 latency evidence"); return d; } auto max=[&](double v,double limit,const char* name){ if(v>limit) d.failures.push_back(name);}; max(e.ackLatencyP95,t.targetAckP95Ms,"ackLatencyP95"); max(e.ackLatencyP99,t.targetAckP99Ms,"ackLatencyP99"); max(e.holdLatencyP95,t.targetHoldP95Ms,"holdLatencyP95"); max(e.emergencyLatchP99,t.targetEmergencyLatchP99Ms,"emergencyLatchP99"); max(e.replayExportP99,t.targetReplayExportP99Ms,"replayExportP99"); d.status=d.failures.empty()?P95P99AcceptanceStatus::Accepted:P95P99AcceptanceStatus::Blocked; return d; } }
